prompt:
请只写一个文件 mc_gate_canary.cpp（C++20，全局 main）。

【硬性约束】
1. 允许 include： "mc_gate_seed.h" "mc_gate_dgp.h" "mc_gate_streams.h" "mc_gate_adapter.h" "mc_gate_baselines.h"
   标准头：<cstdint> <cstddef> <cstdio> <string> <vector> <span>
2. 不要重新定义任何已存在的函数。main 第一行 `using namespace mc_gate;`。
3. 构建带 -Werror，零警告。只打印规定的行。

【已有接口（逐字，不要重定义）】
  std::string dataset_key(const char* comp, double S, int N, int T, double rho,
                          const char* dist, double p, int ds);
  std::uint64_t seed_of(const std::string& key, int rep, int batch, const char* stream, std::uint64_t run_seed);
  int kappa_of(const std::string& key, int rep, int batch, std::uint64_t run_seed, int T);
  ReturnMatrix generate_with_kappa(Family fam, Composition comp, int T, int N, double rho,
                                   double S, std::uint64_t seed, int kappa);
  WindowStats make_window_stats(const ResearchWindow&, bool abstain=false);
  Decision decide_from_stats(const WindowStats&, const RuleConfig&);
  struct RuleConfig { GateMode mode; double q; double alpha; };
  struct ResearchWindow { std::span<const double> returns; std::size_t trials, observations; std::uint64_t returns_sha256; };

【任务：AC-09 金丝雀】
参数：T=100, N=126, rho=0.30, S=50.0, Family::T5, Composition::OneGood,
      run_seed=20261027ULL, reps=20
key = dataset_key("one_good", 50.0, 126, 100, 0.30, "t5", 50.4, 0)

对 rep = 0 .. 19：
    int kappa = kappa_of(key, rep, 0, 20261027ULL, T);            // 来自 assign 子流
    std::uint64_t s = seed_of(key, rep, 0, "ret", 20261027ULL);   // 来自 ret 子流
    ReturnMatrix m = generate_with_kappa(Family::T5, Composition::OneGood, T, N, 0.30, 50.0, s, kappa);
    // trial-major 展平
    std::vector<double> flat((std::size_t)T*(std::size_t)N);
    for(int i=0;i<T;i++) for(int t=0;t<N;t++) flat[(std::size_t)i*N+t]=m.at(i,t);
    ResearchWindow w{ std::span<const double>(flat.data(), flat.size()),
                      (std::size_t)T, (std::size_t)N, 0 };
    Decision d = decide_from_stats(make_window_stats(w,false), RuleConfig{ GateMode::Full, 0.05, 0.05 });
    打印：CANARY <rep> <d.selected?1:0> <(long long)d.index> <kappa>
    统计 hits += (d.selected && (long long)d.index == kappa) ? 1 : 0;

最后打印：CANARY_OK <hits>/20
再打印 CANARY_DONE，return 0。

【输出纪律】20 行 CANARY + 1 行 CANARY_OK + 1 行 CANARY_DONE。
全部 printf 到 stdout，不写 stderr。
